// Generated by `cargo xtask gen` from the tool's Rust output types. Do not edit.

export type StrapEvent =
	| {
			event: "checked";
			schema_version: number;
			target: string;
			rootfs: string;
			/**
			 * The image file's size.
			 */
			rootfs_bytes: number;
			/**
			 * Free space on the target's filesystem.
			 */
			free_bytes: number;
			/**
			 * How many checks ran (waived ones are not counted).
			 */
			checks: number;
	  }
	| {
			event: "start";
			schema_version: number;
			target: string;
			rootfs: string;
			/**
			 * Files, directories and links in the image, below its top directory.
			 */
			total_entries: number;
			/**
			 * The size of its regular files.
			 */
			total_bytes: number;
	  }
	| { event: "progress"; entries: number; bytes: number }
	| { event: "verify" }
	| { event: "done"; schema_version: number; entries: number; bytes: number; duration_ms: number };

export type ExistingEntry = {
	/**
	 * 1-based.
	 */
	line: number;
	spec: string;
	file: string;
	fstype: string;
	/**
	 * Describes a mount point (or swap) that a generated entry also describes.
	 */
	conflicts: boolean;
};

export type FstabEntry = {
	/**
	 * What is mounted (the device, or the swap file's path on the live system).
	 */
	origin: string;
	spec: string;
	/**
	 * The mount point, relative to the root; `none` for swap.
	 */
	file: string;
	fstype: string;
	options: string;
	pass: number;
	/**
	 * The entry as written, its comment line included.
	 */
	text: string;
};

export type FstabResult = {
	schema_version: number;
	root: string;
	/**
	 * `<root>/etc/fstab`.
	 */
	fstab_path: string;
	entries: Array<FstabEntry>;
	/**
	 * The fstab's active lines; empty when it has none or does not exist.
	 */
	existing: Array<ExistingEntry>;
	/**
	 * Things to look at before booting the target; none stops `--write`.
	 */
	warnings: Array<string>;
	/**
	 * `--write` appended the entries (replacing conflicting lines with `--replace`).
	 */
	written: boolean;
};

export type ErrorPayload = {
	schema_version: number;
	/**
	 * `E0NN`; its number is the exit status.
	 */
	code: string;
	message: string;
	/**
	 * What to do about it, when the message alone does not say.
	 */
	remediation?: string;
};

export const STRAP_SCHEMA_VERSION = 1 as const;

export const FSTAB_SCHEMA_VERSION = 1 as const;

export const ERROR_SCHEMA_VERSION = 1 as const;

/** One line of `recstrap --json`; null when the line isn't one. */
export function readStrapEvent(line: string): StrapEvent | null {
	try {
		const value = JSON.parse(line) as { event?: unknown };
		return typeof value?.event === "string" ? (value as StrapEvent) : null;
	} catch {
		return null;
	}
}

/** A failed recstrap or recfstab run's error: the last JSON object on stderr (messages
 * from mount or cp can come before it); null when there is none. */
export function readErrorPayload(stderr: string): ErrorPayload | null {
	const trimmed = stderr.trim();
	const start = trimmed.lastIndexOf("\n{");
	const text = start >= 0 ? trimmed.slice(start + 1) : trimmed.startsWith("{") ? trimmed : "";
	try {
		const value = JSON.parse(text) as Partial<ErrorPayload>;
		return value?.schema_version === ERROR_SCHEMA_VERSION && typeof value.code === "string"
			? (value as ErrorPayload)
			: null;
	} catch {
		return null;
	}
}
